SELECT IF(x.dana = '', '', CONCAT('<br>Menyatakan ahli waris tersebut berhak untuk mengurus pencairan ', x.dana, ';')) AS data FROM (SELECT TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9700 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS dana) x